import{_ as i,o as n,c as a,ai as l}from"./chunks/framework.Ai2o9gNv.js";const o=JSON.parse('{"title":"HarmonyOS Next V2 @Monitor和@Computed","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 @Monitor和@Computed/@Monitor和@Computed.md","filePath":"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 @Monitor和@Computed/@Monitor和@Computed.md","lastUpdated":1730788610000,"__rawMarkdown":"# HarmonyOS Next V2 @Monitor和@Computed\\n\\n## @Monitor 介绍\\n\\n`@Monitor` 是状态把管理V2版本中的用于监听状态变量修改的技术。\\n\\n它可以直接用在\\n\\n1. `@ComponentV2`装饰的自定义组件中，用于被`@Local`、`@Param`、`@Provider`、`@Comsumer`、`@Computed`修饰的状态变量中\\n2. 对于深层次的数据，如深层次对象、对象数组等，需要搭配`@ObservedV2`、`@Trace`一起使用。\\n3. 可以同时监听多个属性\\n4. 可以获取到监听属性的修改前后的数据变化\\n\\n\\n\\n## 对比状态管理V1中的@Watch\\n\\n`@Monitor` 比 `@Watch`功能要强大不少\\n\\n1. `@Watch` 不能用在`@ComponentV2`修饰的\\n2. `@Watch` 不具备深度监听的功能\\n3. `@Watch` 无法同时监听多个属性\\n4. `@Watch` 无法检测 属性修改前后的变化\\n\\n\\n\\n## @Monitor 监听单个属性\\n\\n```typescript\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local num: number = 100\\n\\n  @Monitor(\\"num\\")\\n  changeNum() {\\n    console.log(\\"检测到数据的修改啦\\")\\n  }\\n\\n  build() {\\n    Column() {\\n\\n      Button(`点击修改 ${this.num}`)\\n        .onClick(() => {\\n          this.num++\\n        })\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n```\\n\\n## @Monitor 同时监听多个属性\\n\\n```typescript\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local num: number = 100\\n  @Local age: number = 200\\n\\n  // 同时监听多个状态的修改\\n  @Monitor(\\"num\\",\\"age\\")\\n  changeNum() {\\n    console.log(\\"检测到数据的修改啦\\")\\n  }\\n\\n  build() {\\n    Column() {\\n      Button(`点击修改 num ${this.num}`)\\n        .onClick(() => {\\n          this.num++\\n        })\\n      Button(`点击修改 age ${this.age}`)\\n        .onClick(() => {\\n          this.age++\\n        })\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n```\\n\\n## @Monitor 的回调函数\\n\\n`@Monitor` 的回调函数可以给我们提供这样的能力：\\n\\n1. 如果监听了多个状态，而只有一个状态发生变化时， 可以给获知到具体哪个状态发生了变化\\n2. 当状态发生变化时，可以获取到变化前后的两个值\\n\\n@Monitor 的回调函数的参数是 [IMonitor](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-new-monitor-V5#imonitor%E7%B1%BB%E5%9E%8B)，它是一个对象，拥有两个属性\\n\\n1. `dirty` ，是一个字符串数组，里面存放了修改的状态的名称\\n2. `value`，是一个函数，调用返回会返回一个新的对象，新对象中包含了 `path:修改的状态的名称，before：修改前的数据，now：修改后的数据`，另外  `value()`  调用时，如果不传递参数并且你是同时修改多个状态的话，那么它只会返回第一个状态，如果传递了参数-状态变量  那么就会返回该状态变量的相关信息\\n\\n\\n\\n```typescript\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local num: number = 100\\n  @Local age: number = 200\\n\\n  // 同时监听多个状态的修改\\n  @Monitor(\\"num\\",\\"age\\")\\n  changeNum(Monitor: IMonitor) {\\n    console.log(\\"修改的状态\\", Monitor.dirty)\\n    console.log(\\"Monitor.value()\\", JSON.stringify(Monitor.value(\\"age\\")))\\n\\n  }\\n\\n  build() {\\n    Column() {\\n      Button(`同时修改 num 和 age ${this.num}  ${this.age}`)\\n        .onClick(() => {\\n          this.num++\\n          this.age++\\n        })\\n\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n```\\n\\n## @Monitor 深度监听 \\n\\n`@Monitor` 需要和 `@ObservedV2`、`@Trace`一起使用才能实现深度监听的效果，需要注意的是:\\n\\n1. `@Monitor`可以直接写在 `@ObserveV2` 修饰的`class`中\\n2. `@Monitor` 也可以写在正常的组件内\\n\\n```typescript\\n@ObservedV2\\nclass Person {\\n  @Trace son: Son = new Son()\\n}\\n\\n@ObservedV2\\nclass Son {\\n  // @Monitor可以直接写在 @ObserveV2 修饰的class中\\n  @Monitor(\\"weight\\")\\n  weightChange() {\\n    console.log(\\"1 儿子的体重修改了\\")\\n  }\\n\\n  @Trace weight: number = 200\\n}\\n\\n\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  person: Person = new Person()\\n    // @Monitor 也可以写在正常的组件内\\n  @Monitor(\\"person.son.weight\\")\\n  weightChange() {\\n    console.log(\\"2 儿子的体重呗修改了\\")\\n  }\\n\\n  build() {\\n    Column() {\\n      Button(`修改儿子的体重${this.person.son.weight}`)\\n        .onClick(() => {\\n          this.person.son.weight++\\n        })\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n```\\n\\n\\n\\n## @Monitor的限制\\n\\n在实际开发使用中，`@Monitor`也存在一些限制，无法监听内置类型（`Array`、`Map`、`Date`、`Set`）的API调用引起的变化，如当你检测整个数组时，你对数组使用 `push`、`splice`等常见方法修改数组，是无法检测到的。当然，当整个数组被重新赋值时，可以检测到它的变化\\n\\n```typescript\\n@ObservedV2\\nclass Person {\\n  @Trace name: string = \\"小明\\"\\n}\\n\\n\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local\\n  personList: Person[] = [new Person()]\\n\\n  @Monitor(\\"personList\\")\\n  weightChange() {\\n    console.log(\\" 检测到数组修改了\\")\\n  }\\n\\n  build() {\\n    Column() {\\n      Button(\\"增加一个\\")\\n        .onClick(() => {\\n          // 1 无效 - 无法检测到数组发生了修改\\n          this.personList.push(new Person())\\n\\n\\n          // 2 有效 检测到了数组发生修改\\n          // const newPerson = [...this.personList, new Person()]\\n          // this.personList = newPerson\\n        })\\n      ForEach(this.personList, (item: Person) => {\\n        Text(item.name)\\n      })\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n```\\n\\n另外可以通过.语法或者监听数组长度来变向实现检测数组元素发生变化\\n\\n**.语法**\\n\\n```typescript\\n@ObservedV2\\nclass Person {\\n  @Trace name: string = \\"小明\\"\\n}\\n\\n\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local\\n  personList: Person[] = [new Person()]\\n\\n  @Monitor(\\"personList.0\\")\\n  // 如果要单独监听对象中的某个属性  @Monitor(\\"personList.0.name\\")\\n  weightChange() {\\n    console.log(\\" 检测到数组修改了\\")\\n  }\\n\\n  build() {\\n    Column() {\\n      Button(\\"增加一个\\")\\n        .onClick(() => {\\n          const p = new Person()\\n          p.name = \\"小黑\\"\\n          this.personList[0] = p\\n        })\\n      ForEach(this.personList, (item: Person) => {\\n        Text(item.name)\\n      })\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n```\\n\\n\\n\\n**监听数组长度变化**\\n\\n```typescript\\n@ObservedV2\\nclass Person {\\n  @Trace name: string = \\"小明\\"\\n}\\n\\n\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local\\n  personList: Person[] = [new Person()]\\n\\n  @Monitor(\\"personList.length\\")\\n  weightChange() {\\n    console.log(\\" 检测到数组修改了\\")\\n  }\\n\\n  build() {\\n    Column() {\\n      Button(\\"增加一个\\")\\n        .onClick(() => {\\n          const p = new Person()\\n          p.name = \\"小黑\\"\\n          this.personList.push(p)\\n        })\\n      ForEach(this.personList, (item: Person) => {\\n        Text(item.name)\\n      })\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n```\\n\\n\\n\\n## @Computed\\n\\n`@Computed`为计算属性，可以监听数据变化，从而计算新的值。用法比较简单\\n\\n```typescript\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local num: number = 100\\n\\n  @Computed\\n  get numText() {\\n    return this.num * 2\\n  }\\n\\n  build() {\\n    Column() {\\n      Button(\\"修改\\")\\n        .onClick(() => {\\n          this.num++\\n        })\\n      Text(`原数据 ${this.num}`)\\n      Text(`计算后 ${this.numText}`)\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n```\\n\\n"}'),p={name:"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 @Monitor和@Computed/@Monitor和@Computed.md"};function h(e,s,t,k,r,E){return n(),a("div",null,[...s[0]||(s[0]=[l("",33)])])}const c=i(p,[["render",h]]);export{o as __pageData,c as default};
